const ethers = require("ethers");

function main(stream) {
    const iface = new ethers.Interface([{
        name: 'Transfer',
        type: 'event',
        inputs: [
            { indexed: true,  name: 'from',  type: 'address' },
            { indexed: true,  name: 'to',    type: 'address' },
            { indexed: false, name: 'value', type: 'uint256' }
        ]
    }]);

    const topic = iface.getEvent('Transfer').topicHash;

    let best = null;
    let bestValue = BigInt(0);

    for (const log of stream.logs || []) {
        if (!log.topics || String(log.topics[0]).toLowerCase() !== topic) continue;
        let args;
        try { args = iface.parseLog(log).args; } catch { continue; }
        const value = BigInt(args.value.toString());
        if (value <= bestValue) continue;
        bestValue = value;
        best = {
            hash: log.transactionHash,
            contract: String(log.address).toLowerCase(),
            from: args.from,
            to: args.to,
            rawAmount: args.value.toString()
        };
    }

    if (!best) return null;

    return {                      // filled downstream from CoinGecko metadata
        contract: best.contract,
        from: best.from.toLowerCase(),
        to: best.to.toLowerCase(),
        rawAmount: best.rawAmount,       // raw units - Amount Resolve scales it
        network: "ethereum-mainnet",     // keep in sync with Network in the trigger
        txHash: best.hash
    };
}

parameters.jsCode:
// Run mode: 'Run Once for All Items' - the whale gate, placed BEFORE the GoPlus and
// Sheets enrichment branches: sub-$100k events are dropped here, so their API quota is
// only spent on events that can actually alert. Unvaluable events are KEPT - we never
// dismiss an event by a USD value we could not compute (P2 floor downstream).
// Dropped events are expressed by returning a filtered array with explicit `pairedItem`
// input indices (docs: "Preserving linking in the Code node").
const WHALE_MIN_USD = 100000; // the whale filter - on converted USD value, never on rawAmount

const inputs = $input.all();
const kept = [];
for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i].json;
  if (item.usdValue !== null && item.usdValue < WHALE_MIN_USD) continue;
  kept.push({ json: item, pairedItem: i });
}
return kept;

// Atria networkId -> enrichment endpoints (CoinGecko platform slug, GoPlus numeric
// chain). THE single network map of this workflow: the Atria Trigger stamps `network`
// on every event; Amount Resolve re-reads these rows to stamp chainId. Unmapped values
// (testnets, non-EVM) never produce a request here - the documented degradation applies
// downstream: unresolved meta -> usdValue null, never auto-dropped.
// Supported chains: Ethereum + Polygon mainnets. Testnets (incl. ethereum-sepolia) are
// deliberately left unmapped -> they degrade to usdValue null, never a bogus CoinGecko
// request. Add a chain by extending this map; no other node needs to change.
const NETWORKS = {
  'ethereum-mainnet': { chainId: 1, cgPlatform: 'ethereum' },
  'polygon-mainnet': { chainId: 137, cgPlatform: 'polygon-pos' },
};

// Run mode: 'Run Once for All Items' - external-call dedup: the CoinGecko contract
// endpoint returns the SAME payload for every transfer of one token, so a batch of
// events collapses into ONE request per unique (network, contract).
// This branch is a dead-end leaf: Amount Resolve indexes the responses by address (the
// canvas invariant wants this chain ABOVE Amount Resolve).
const seen = new Set();
const kept = [];
for (const { json: envelope } of $input.all()) {
  // the Atria Trigger delivers the whole webhook body: normalized fields live under `data`
  const item = envelope.data ?? envelope;
  const net = NETWORKS[item.network];
  if (!net || !item.contract) continue; // unmapped network: no CG endpoint exists for it
  const key = [item.network, item.contract].join('|');
  if (seen.has(key)) continue;
  seen.add(key);
  kept.push({ json: { network: item.network, contract: item.contract, chainId: net.chainId, cgPlatform: net.cgPlatform } });
}
return kept;

// Run mode: 'Run Once for All Items' - the CoinGecko branch above (Unique Contracts)
// deduplicates external calls by token and ends as a leaf, so responses are mapped
// here by contract address: one request serves every transfer of the same token in
// the batch. Explicit pairedItem keeps the trigger's item indices intact downstream.
// Canvas invariant (n8n executionOrder v1): the Unique Contracts -> CoinGecko leaf
// chain must stay ABOVE this node - mis-dragged, the map is empty and every event
// degrades to unvaluable, not a crashed execution.
// This is the only node that turns token units into numbers with scale.
const chainOf = {};
try {
  for (const r of $('Unique Contracts').all()) chainOf[r.json.network] = r.json; // network -> endpoints
} catch (err) { /* branch not executed - chainId stays null, GoPlus degrades */ }

const respByContract = {};
try {
  for (const r of $('Token Price & Meta (CoinGecko)').all()) {
    const j = r.json || {};
    // coins/<platform>/contract/<address> answers with `contract_address` (older API used
    // `token_address`); failed calls pass the input through and still carry `contract`.
    const addr = String(j.token_address ?? j.contract_address ?? j.contract ?? '').toLowerCase();
    if (addr) respByContract[addr] = j; // failed calls pass the input through (+ error)
  }
} catch (err) { /* branch not executed - everything stays unvaluable */ }

const inputs = $input.all();
const kept = [];
for (let i = 0; i < inputs.length; i++) {
  const source = inputs[i].json;
  // trigger envelope: {feedId, blockNumber, dataSizeBytes, isTestExecution, data:{…}}
  const base = { ...(source.data ?? source) };
  if (source.blockNumber !== undefined) base.blockNumber = source.blockNumber;
  const resp = respByContract[String(base.contract ?? '').toLowerCase()] || {};
  const tokenInfo = resp.token_info || {};
  // `/coins/{platform}/contract/{address}` returns decimals per platform, not as
  // tokenInfo.decimals - fall back through detail_platforms before giving up.
  const platform = base.cgPlatform ?? chainOf[base.network]?.cgPlatform;
  const detail = (resp.detail_platforms || {})[platform] || {};

  const rawDecimals = resp.decimals ?? detail.decimal_place ?? tokenInfo.decimals;
  const decimals = rawDecimals == null || Number.isNaN(Number(rawDecimals)) ? null : Number(rawDecimals);
  const amount = decimals === null
    ? null // unresolvable metadata - do not guess a scale
    : Math.round(Number(base.rawAmount) / 10 ** decimals * 100) / 100;

  const canonicalSymbol = resp.symbol ?? tokenInfo.symbol ?? null;
  let price = Number(resp.market_data?.current_price?.usd ?? 0);
  let priceSource;
  if (price > 0) {
    priceSource = 'coingecko';
  } else if (['usdt', 'usdc', 'dai'].includes(String(canonicalSymbol ?? base.token).toLowerCase())) {
    price = 1; // stables are $1 for our purposes even if the price block failed
    priceSource = 'stable-fallback';
  } else {
    price = null;
    priceSource = 'missing';
  }

  const usdValue = amount === null || price === null
    ? null
    : Math.round(amount * price * 100) / 100;

  kept.push({
    json: {
      ...base,
      chainId: chainOf[base.network]?.chainId ?? null,
      cgPlatform: chainOf[base.network]?.cgPlatform ?? null,
      cgId: resp.id ?? null,
      canonicalSymbol,
      decimals,
      amount,
      price,
      priceSource,
      usdValue,
      metaState: resp.error || decimals === null ? 'unresolved' : 'resolved',
    },
    pairedItem: i,
  });
}
return kept;

// Run mode: 'Run Once for All Items' - GoPlus dedup: token_security accepts a comma
// list of addresses and returns a dict keyed by each of them, so all whale transfers
// in a batch collapse into ONE request per chain (capped at 30 addresses/call - the
// free-tier limit). Unmapped networks (chainId null) get no request here.
const byChain = {};
for (const { json: item } of $input.all()) {
  if (item.chainId == null || !item.contract) continue;
  (byChain[item.chainId] = byChain[item.chainId] || new Set()).add(item.contract);
}
const kept = [];
for (const chainId of Object.keys(byChain)) {
  const addrs = [...byChain[chainId]];
  for (let c = 0; c < addrs.length; c += 30) {
    kept.push({ json: { chainId, addresses: addrs.slice(c, c + 30).join(',') } });
  }
}
// This branch feeds input 1 of the Safety Join, and the join waits for data on BOTH of
// its inputs - a branch that delivers zero items never fills its slot and stalls the
// whole run. So it always emits at least one row: `skip: true` makes the GoPlus URL
// query the zero address, which answers {"code":1,"result":{}} at HTTP 200 - a real
// response that matches no contract and is ignored by Safety Resolve.
if (kept.length === 0) kept.push({ json: { chainId: null, addresses: '', skip: true } });
return kept;

// Run mode: 'Run Once for All Items' - TOKEN SAFETY ONLY: attaches GoPlus security
// flags to each whale event. Pricing already happened upstream in Amount Resolve.
//
// Its input is the Safety Join: whale events (input 0) and GoPlus answers paired with
// their request (input 1). Items are told apart by SHAPE, not by source node: an event
// carries `rawAmount` (the trigger's filter always stamps it), a GoPlus body never does.
//
// The responses arrive already merged with the Unique Whale Contracts row that produced
// them (a combineByPosition merge), which matters: GoPlus answers with
// {code, message, result} and NO chain identifier, so an address that exists on two chains
// would otherwise inherit whichever chain answered first. Everything is therefore keyed by
// `chainId|address` and a Polygon event can never be marked clean by an Ethereum answer.
//
// Semantics mirror Classify & Score in the reference workflow: flags come back as STRINGS
// ('0' / '1'); a failed call carries `error` and the addresses it asked for, so those
// become null - "asked, got nothing". Absent and null both mean unavailable, and no event
// is ever dropped for it.
const RISKY_FIELDS = ['is_honeypot', 'is_mintable', 'is_owner_changeable', 'hidden_owner', 'is_blacklisted'];

const isEvent = (json) => !!json && typeof json === 'object' && json.rawAmount !== undefined;

// batch rows carry chainId as a STRING (Object.keys), events as a NUMBER (NETWORKS map)
const key = (chainId, addr) => `${String(chainId ?? '')}|${String(addr ?? '').toLowerCase()}`;

const safetyByKey = {};
let responses = 0;
for (const { json: item } of $input.all()) {
  if (isEvent(item)) continue;
  if (item.result) {
    responses++;
    // one request covers up to 30 addresses - index every entry against THIS chain
    for (const [addr, flags] of Object.entries(item.result)) {
      safetyByKey[key(item.chainId, addr)] = flags;
    }
  } else if (item.error || item.addresses) {
    responses++;
    for (const addr of String(item.addresses ?? '').split(',')) {
      if (addr) safetyByKey[key(item.chainId, addr)] = null;
    }
  }
}

const inputs = $input.all();
const kept = [];
for (let i = 0; i < inputs.length; i++) {
  const source = inputs[i].json;
  if (!isEvent(source)) continue; // GoPlus bodies end their journey here

  // undefined = never queried, null = queried but the call failed, object = an answer
  const entry = safetyByKey[key(source.chainId, source.contract)];
  const safety = entry || {};
  const risks = RISKY_FIELDS.filter((k) => safety[k] != null && String(safety[k]) !== '0');
  const notes = [];
  if (!entry) notes.push('safety-check-unavailable');
  if (source.metaState !== 'resolved') notes.push('token-meta-unavailable');

  kept.push({
    json: {
      ...source,
      // 'unavailable' - never 'clean' - whenever GoPlus gave us nothing for this chain+address
      safetyState: !entry ? 'unavailable' : (risks.length ? 'risky' : 'clean'),
      safetyFlags: [...risks, ...notes].join(', ') || 'none',
      safetyResponses: responses,
    },
    pairedItem: i,
  });
}
return kept;

// Run mode: 'Run Once for All Items' - counterparty labelling. Known Wallets (Sheets)
// is a read-only leaf hanging off Whale Gate; it is consumed here by name (same pattern
// as Unique Contracts -> CoinGecko -> Amount Resolve), which keeps the branch clear of
// the Safety Join: that join waits for data on BOTH inputs, so a wallets tab with zero
// rows would stall the run.
//
// The lookup is a plain in-memory map built once per batch - no per-event request, no
// filter node. Everything the workflow cannot label stays 'unknown', which downstream
// scoring treats as "no evidence", never as "safe". No event is dropped here.
let walletRows = [];
try {
  walletRows = $('Known Wallets (Sheets)').all().map((i) => i.json);
} catch (err) { /* branch not executed or Sheets failed - every label stays 'unknown' */ }

const labelByAddress = new Map();
for (const row of walletRows) {
  const addr = String(row?.address ?? '').trim().toLowerCase();
  const label = String(row?.label ?? '').trim();
  if (addr && label) labelByAddress.set(addr, label); // later rows win on duplicates
}

const labelOf = (addr) => labelByAddress.get(String(addr ?? '').trim().toLowerCase()) ?? 'unknown';

const inputs = $input.all();
const kept = [];
for (let i = 0; i < inputs.length; i++) {
  const source = inputs[i].json;
  kept.push({
    json: {
      ...source,
      capturedAt: new Date().toISOString(), // write-time clock: Last Hour Events filters the ledger on this
      fromLabel: labelOf(source.from),
      toLabel: labelOf(source.to),
      knownWalletsLoaded: labelByAddress.size, // 0 means the tab is empty or unreadable
    },
    pairedItem: i,
  });
}
return kept;

// Run mode: 'Run Once for All Items' - collapses the whole ledger read into ONE summary item.
//
// 'Read Ledger Rows' hands over the entire 'Whale transfers' tab every hour: Sheets has no
// server-side filter we can push down here, so the window is applied in memory. The slice
// cap bounds the read the way the reference intends - the weekly ledger rotation (not
// ported yet) is what keeps the tab small; until then the cap is the safety net.
//
// Window key is capturedAt, stamped by Known Wallet Labels at append time. Date.parse of a
// non-timestamp returns NaN, so a row without one (or a Sheets error item from onError) is
// filtered out rather than thrown on. A quiet hour returns [] - no digest item, so nothing
// is appended and no chat noise is made. That is the only sane "no news" signal here.
const WINDOW_MS = 3600000;
const now = Date.now();
const num = (v) => {
	const n = Number(v);
	return Number.isFinite(n) ? n : 0;
};

const rows = [];
for (const raw of $input.all().map((i) => i.json).slice(-5000)) {
	const at = Date.parse(raw.capturedAt ?? raw.time ?? '');
	if (Number.isFinite(at) && now - at >= 0 && now - at < WINDOW_MS) rows.push({ ...raw, at });
}
if (!rows.length) return [];

// USD bands and safety states. 'usdValue' is already converted human-readable money here:
// Amount Resolve computed it as amount * price (human amount, not rawAmount) and stamped
// priceSource 'missing' when CoinGecko had no quote. So: banding on usdValue is correct, and
// a 'missing' price contributes 0 rather than inventing a number - a $0 line in a whale digest
// reads as "could not price it", which is honest, whereas hiding it would understate the hour.
// The tiers mirror the reference's severity thresholds (20M / 5M) plus its whale floor, so the
// digest reads the same way whether or not Classify & Score is ported later.
const BANDS = [
	['mega', 20e6],
	['large', 5e6],
	['medium', 1e6],
	['gate', 0],
];
const bandOf = (u) => (u > 0 ? ((BANDS.find(([, min]) => u >= min) ?? ['gate', 0])[0]) : null);
const bands = { mega: 0, large: 0, medium: 0, gate: 0 };
const safety = { clean: 0, risky: 0, unavailable: 0 };
const riskyContracts = new Set();
const unpriced = { count: 0, contracts: new Set(), rawTokens: 0 };
const tokens = new Map();
const venues = new Map();
let totalUsd = 0;

for (const r of rows) {
	const usd = num(r.usdValue);
	totalUsd += usd;
	const band = bandOf(usd);
	if (band) bands[band]++;

	if (r.priceSource === 'missing') {
		unpriced.count++;
		unpriced.contracts.add(String(r.contract).toLowerCase());
		if (String(r.metaState) === 'resolved') unpriced.rawTokens += num(r.amount);
	}

	const state = r.safetyState === 'clean' || r.safetyState === 'risky' ? r.safetyState : 'unavailable';
	safety[state]++;
	if (state === 'risky') riskyContracts.add(String(r.contract).toLowerCase());

	const sym = String(r.canonicalSymbol || r.token || r.contract || 'unknown').toUpperCase();
	const t = tokens.get(sym) ?? { symbol: sym, count: 0, usd: 0 };
	t.count++;
	t.usd += usd;
	tokens.set(sym, t);

	// flow INTO a labelled wallet is the desk-relevant direction: an exchange address on
	// the receiving end is an inflow (deposit), on the sending end an outflow (sell signal).
	for (const [label, key] of [[r.toLabel, 'to'], [r.fromLabel, 'from']]) {
		const name = String(label ?? '').trim();
		if (!name || name === 'unknown') continue;
		const v = venues.get(name) ?? { label: name, inflows: 0, outflows: 0, usd: 0 };
		v[key === 'to' ? 'inflows' : 'outflows']++;
		v.usd += usd;
		venues.set(name, v);
	}
}

const top = [...rows]
	.sort((a, b) => num(b.usdValue) - num(a.usdValue))
	.slice(0, 5)
	.map((r) => ({
		symbol: String(r.canonicalSymbol || r.token || 'unknown').toUpperCase(),
		amount: num(r.amount),
		usdValue: num(r.usdValue),
		fromLabel: r.fromLabel ?? 'unknown',
		toLabel: r.toLabel ?? 'unknown',
		safetyState: r.safetyState ?? 'unavailable',
		txHash: String(r.txHash ?? '').slice(0, 10),
	}));

// Severity counts, because the reference's Telegram and Slack templates read p1/p2 and the
// ledger has no severity column: Classify & Score was never ported. Rather than rename the
// template, this node derives severity with that node's own thresholds, from columns the
// ledger really carries (usdValue, fromLabel, priceSource, from) - see the reference body:
//
//   P1  usd >= 20M, or usd >= 5M from an unknown sender that is NOT moving funds to an exchange
//   P2  usd >= 5M, or >= 3 events from the same sender in the hour, or no reliable USD value
//   P3  everything else
//
// Two honest approximations, both flagged here rather than hidden:
//   * "not outflowToExchange" is Classify & Score's exchange-address list, which this workflow
//     does not have. A 5M+ transfer from an unlabelled wallet INTO an exchange therefore reads
//     P1 where the reference would call it P2. Over-flagging is the safe direction to err.
//   * the >=3 burst is counted inside this one-hour window; the reference counted it from
//     staticData across a longer memory, so a burst that straddles the hour boundary counts
//     lower here.
const senderCount = new Map();
for (const r of rows) {
	const k = String(r.from).toLowerCase();
	senderCount.set(k, (senderCount.get(k) ?? 0) + 1);
}
const sevOf = (r) => {
	const u = num(r.usdValue);
	const unknownSender = !String(r.fromLabel ?? '').trim() || String(r.fromLabel).toLowerCase() === 'unknown';
	const burst = (senderCount.get(String(r.from).toLowerCase()) ?? 0) >= 3;
	if (String(r.priceSource) === 'missing') return 'p2'; // unpriceable = review, never discard
	if (u >= 20e6 || (u >= 5e6 && unknownSender)) return 'p1';
	if (u >= 5e6 || burst) return 'p2';
	return 'p3';
};
const sev = { p1: 0, p2: 0, p3: 0 };
for (const r of rows) sev[sevOf(r)]++;

return [
	{
		json: {
			windowStart: new Date(now - WINDOW_MS).toISOString(),
			windowEnd: new Date(now).toISOString(),
			ledgerRowsRead: Math.min($input.all().length, 5000),
			count: rows.length,
			totalUsd: Math.round(totalUsd),
			...bands,
			...sev,
			p1Contracts: rows.filter((r) => sevOf(r) === 'p1').map((r) => String(r.contract).toLowerCase()).slice(0, 5),
			safetyClean: safety.clean,
			safetyRisky: safety.risky,
			safetyUnavailable: safety.unavailable,
			riskyContracts: [...riskyContracts],
			unpriced: { count: unpriced.count, contracts: [...unpriced.contracts], rawTokens: Math.round(unpriced.rawTokens) },
			top,
			tokens: [...tokens.values()].sort((a, b) => b.usd - a.usd).slice(0, 5),
			venues: [...venues.values()].sort((a, b) => b.usd - a.usd).slice(0, 5),
		},
	},
];

// Run mode: 'Run Once for All Items'. Turns the model's reply into one Telegram-safe message.
//
// Everything the model produced is HTML-escaped and stripped of markdown markers before it
// reaches Telegram: parse_mode is HTML, so an unescaped '<' or '&' is a 400, and n8n's fallback
// parse_mode (Markdown, legacy) treats every '*' as an entity that must be paired. Neither is
// allowed to happen, and a digest that cannot be formatted must still be sent, so the fallbacks
// here degrade the *shape*, never the delivery.
const j = $input.first().json;
// an agent whose provider failed is set to continue rather than abort the hour, and in that case
// it forwards the trunk item with no "output" at all: distinguish "answered with nothing" from
// "never answered", because dumping the input JSON as a bullet would be neither readable nor safe
const replied = typeof j.output === 'string' || typeof j.text === 'string';
const raw = replied ? String(j.output ?? j.text) : '';

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// slice BEFORE escaping: cutting a string after esc() can end it inside '&amp;' and Telegram
// rejects the dangling entity exactly like it rejects an unpaired '*'
const clean = (s) =>
	esc(
		String(s)
			.replace(/^\s*[-*\u2022]\s+/, '') // the model's own bullets: Telegram draws them
			.replace(/[*_~`]/g, '') // markdown emphasis is literal noise in HTML mode
			.replace(/\s+/g, ' ')
			.trim()
			.slice(0, 300),
	);

// widest plausible JSON object: fenced block, then outer braces, then the raw text as a last guess
const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
const open = raw.indexOf('{');
const close = raw.lastIndexOf('}');
const attempts = [fenced ? fenced[1] : '', open > -1 && close > open ? raw.slice(open, close + 1) : '', raw].filter(Boolean);

let parsed = null;
for (const a of attempts) {
	try {
		const v = JSON.parse(a);
		if (v && typeof v === 'object' && !Array.isArray(v)) { parsed = v; break; }
		if (Array.isArray(v)) { parsed = { bullets: v }; break; }
	} catch (e) {
		// not JSON: fall through to the next candidate
	}
}

let headline = '';
let bullets = [];
if (parsed) {
	if (typeof parsed.headline === 'string') headline = clean(parsed.headline);
	const arr = parsed.bullets ?? parsed.lines ?? parsed.items ?? parsed.digest;
	const list = Array.isArray(arr) ? arr : typeof arr === 'string' ? arr.split(/\n+/) : [];
	bullets = list.map(clean).filter(Boolean);
}
if (!bullets.length) {
	// the model ignored the contract: render what it said, line by line, rather than nothing -
	// except the literal non-answers, which would otherwise print as a bullet saying "null"
	const nothing = new Set(['', 'null', 'undefined', 'NaN', '{}', '[]']);
	if (!nothing.has(String(raw).trim())) {
		bullets = String(raw)
			.split(/\n+/)
			.map(clean)
			.filter(Boolean);
	}
}
bullets = bullets.slice(0, 8);

let stats = {};
try {
	stats = $('Last Hour Events').first().json || {};
} catch (e) {
	stats = {}; // reading the trunk by name must never be the reason no message goes out
}
// when the agent was skipped by its own error policy it forwards the item it was given, which IS
// the trunk summary: prefer that over an empty header, because the numbers come from the ledger
if (!replied) stats = { ...stats, ...j };
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const money = (v) => '$' + num(v).toLocaleString('en-US');
// the glyphs are written literally: they are what the chat shows, and a code node the user can
// read in the editor should not be a wall of \uXXXX escapes
const head =
	'📊 <b>Hourly whale digest</b> - ' + num(stats.count) + ' transfers, ≈' + money(stats.totalUsd) +
	' (<b>' + num(stats.p1) + ' P1</b> · <b>' + num(stats.p2) + ' P2</b> · ' + num(stats.p3) + ' P3)';

// Telegram caps a message at 4096 chars and n8n appends its attribution footer; drop whole
// bullets rather than slicing mid-entity, which would leave '&amp' and fail the send.
const MAX = 3600;
const lines = bullets.map((b) => '• ' + b);
if (headline) lines.unshift('<b>' + headline + '</b>');
let body = lines.join('\n');
while (head.length + body.length > MAX && lines.length > 1) {
	lines.pop();
	body = lines.join('\n') + '\n… truncated';
}
const text = bullets.length
	? head + '\n\n' + body
	: head + '\n\n• ' + (replied ? 'the model returned nothing to show' : 'the digest writer did not answer (provider error), so these totals are the whole digest');

return [{ json: { text, bulletCount: bullets.length, structured: Boolean(parsed), modelReplied: replied, chars: text.length } }];

// Run mode: 'Run Once for All Items' - decides the age split, writes nothing.
//
// Whether a row may be archived is decided by AGE, and the age key is capturedAt. A row carrying
// no parsable stamp used to end the walk outright, which meant a ledger whose earliest rows
// predate the capturedAt column could never release anything - those rows sit above every stamped
// row and blocked it at index 0. The inference below is what the branch needs to be useful.
//
// The ledger is appended to and never reordered, so age order == sheet order and the archive set
// is a CONTIGUOUS PREFIX of the read: walk from the top, stop at the first row that is not
// provably older than the cutoff. That property is what lets 'Plan Prune Range' talk in row
// numbers instead of row identities.
//
// How an age is proved:
//   1. its own capturedAt, when that parses as an ISO date - see stamp() below;
//   2. otherwise INHERITED from the nearest row BELOW it that has one. Append-only means row i was
//      written before row i + 1, so anything above a provably old row is at least as old as it.
//      This is what unblocks a ledger whose first rows predate the capturedAt column: they have no
//      stamp of their own, and they sit above rows that do.
//   3. still unknown when NOTHING below it carries a stamp - no witness, no inference. Such a row
//      ends the walk and stays in the ledger rather than being archived and deleted on a guess.
//      A hand-written row appended at the bottom is the case this protects.
const RETAIN_DAYS = 7;
const cutoff = Date.now() - RETAIN_DAYS * 24 * 3600e3;
// Only an ISO-looking stamp is a date. Date.parse('0') is the year 2000 and Date.parse('1') is
// the 1st of this month, so a blank cell, a stray 0, or a hand-typed note would otherwise read as
// ancient and get archived. The ledger writes new Date().toISOString(), so this gate accepts what
// the workflow produces and refuses everything else.
const stamp = (r) => {
  const s = String(r?.capturedAt ?? '');
  if (!/^\d{4}-\d{2}-\d{2}([T ].*)?$/.test(s)) return NaN;
  return Date.parse(s);
};

const rows = $input.all().map((i) => i.json);
const times = rows.map(stamp);
// One backward pass: each row's own stamp, or the nearest one below it. Row i entered the sheet
// before row i + 1, so an unstamped row is at least as old as the first stamped row beneath it -
// that row is the witness. A row with no witness anywhere below it keeps NaN and stops the walk.
const effective = new Array(times.length);
let witness = NaN;
for (let i = times.length - 1; i >= 0; i--) {
  if (Number.isFinite(times[i])) witness = times[i];
  effective[i] = witness;
}

let splitIndex = 0;
while (splitIndex < rows.length && effective[splitIndex] < cutoff) {
  // '<' and not '<=': NaN fails it too, so an unknown age always ends the walk
  splitIndex++;
}
if (splitIndex === 0) {
  return []; // nothing provably older than the retention window - archive and prune never run
}

// The rows the ledger is about to lose, in read order, unchanged: 'Archive Old Rows' writes them
// back out by column name, so anything reshaped here would surface as a corrupt archive tab.
return rows.slice(0, splitIndex).map((json) => ({ json }));

// Run mode: 'Run Once for All Items' - exactly one item out, whatever the split archived.
//
// Emits the row range 'Prune Ledger Rows' deletes. Row 1 is the header, so data starts at row 2,
// and the split guarantees the archived rows are the first N of the read: start + N - 1 is their
// last sheet row. Counted from $('Partition Ledger Rows') rather than from this node's input, so
// the range can never disagree with what was actually filed into the archive.
const archived = $('Partition Ledger Rows').all();
if (!archived.length) return [];
return [
  {
    json: {
      startRow: 2,
      amountToDelete: archived.length,
    },
  },
];

// Run mode: 'Run Once for All Items' - drops transfers Amount Resolve could not price,
// i.e. `usdValue === null`, BEFORE they reach the whale gate and spend GoPlus/Sheets quota.
// This is the only place that discards an event for a missing USD value: Whale Gate below
// deliberately KEEPS unvaluable events (it filters only on a value it could compute), so the
// "ignore unpriced transfers" request belongs here, one node upstream of the gate.
// Explicit pairedItem keeps the trigger’s item indices intact for every branch downstream.
const inputs = $input.all();
const kept = [];
for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i].json;
  if (item.usdValue === null || item.usdValue === undefined) continue;
  kept.push({ json: item, pairedItem: i });
}
return kept;
